widget.solution:
import math


def quad_call(S0, K, r, sigma, T, n):
    m, s = (r - sigma ** 2 / 2) * T, sigma * math.sqrt(T)
    U = S0 * math.exp(m + 8 * s)
    h = (U - K) / n          # the grid starts at the strike

    def f(S):
        z = (math.log(S / S0) - m) / s
        return (S - K) * math.exp(-z * z / 2) / (math.sqrt(2 * math.pi) * S * s)

    tot = f(K) + f(U)
    for k in range(1, n):
        tot += (4 if k % 2 else 2) * f(K + k * h)
    return math.exp(-r * T) * tot * h / 3

