widget.solution:
import math
import numpy as np


def parity_fit(strikes, calls, puts):
    K, C, P = (np.asarray(v, float) for v in (strikes, calls, puts))
    ok = ~(np.isnan(C) | np.isnan(P))
    if ok.sum() < 2:
        raise ValueError('need two strikes with both prices')
    A = np.column_stack([np.ones(ok.sum()), -K[ok]])   # C - P = D*F - D*K
    a, D = np.linalg.lstsq(A, (C - P)[ok], rcond=None)[0]
    return float(D), float(a / D)
